function extractIntentAndSlots(query) {
  const intents = ['info', 'api', 'example'];
  const slots = ['language', 'framework', 'version'];
  // Lightweight classifier implementation
  return { intent: classify(query, intents), slots: extract(query, slots) };
}

async function hybridRetrieve(query, k=10) {
  const denseResults = await denseSearch(query, k);
  const bm25Results = await bm25Search(query, k);
  return fuseResults(denseResults, bm25Results);
}
```

